const body = $json.body || $json;
const transcript = body.transcript || body.call?.transcript || body.call_analysis?.transcript || '';
const call = body.call || body;
return [{ json: {
  call_id: call.call_id || call.id || body.call_id || '',
  direction: call.direction || body.direction || '',
  from_number: call.from_number || body.from_number || '',
  to_number: call.to_number || body.to_number || '',
  started_at: call.started_at || body.started_at || '',
  ended_at: call.ended_at || body.ended_at || '',
  duration_seconds: call.duration_seconds || body.duration_seconds || 0,
  transcript,
  recording_url: call.recording_url || body.recording_url || '',
  known_contact_context: body.known_contact_context || {},
  raw: body
}}];

