parameters.jsCode:
const content = $json.choices?.[0]?.message?.content || '{}';
let analysis;
try { analysis = JSON.parse(content); } catch (e) { analysis = { parse_error: true, raw_content: content }; }
return [{ json: { ...$('Normalize Call Payload').first().json, analysis } }];

const a = $('Parse Analysis').first().json.analysis;
const base = $('Parse Analysis').first().json;
const contactId = $json.id || $json.vid || $json.properties?.hs_object_id || '';
const note = `AI Voice Call Summary

Direction: ${base.direction}
Caller Type: ${a.caller_type || ''}
Primary Intent: ${a.primary_intent || ''}
Sentiment: ${a.sentiment?.label || ''} (${a.sentiment?.score ?? ''})
Lead Quality: ${a.lead_quality || ''}
Escalation Required: ${a.human_escalation_required ? 'Yes' : 'No'}

Summary:
${a.summary || ''}

Captured Details:
Name: ${a.entities?.name || ''}
Email: ${a.entities?.email || ''}
Phone: ${a.entities?.phone || base.from_number || ''}
Company: ${a.entities?.company || ''}
Location: ${a.entities?.location || ''}
Service Interest: ${a.entities?.service_interest || ''}
Budget: ${a.entities?.budget || ''}
Timeline: ${a.entities?.timeline || ''}
Preferred Callback: ${a.entities?.preferred_callback_time || ''}

Questions Asked:
${(a.questions_asked || []).map(q => '- ' + q).join('
')}

Objections / Concerns:
${(a.objections || []).map(o => '- ' + o).join('
')}

Recommended Next Step:
${a.next_action || ''}

Recording:
${base.recording_url || ''}`;
const due = new Date();
if (a.task_due_rule === 'same_business_hour') due.setHours(due.getHours() + 1);
else if (a.task_due_rule === 'two_business_hours') due.setHours(due.getHours() + 2);
else if (a.task_due_rule === 'next_business_day') due.setDate(due.getDate() + 1);
else due.setDate(due.getDate() + 3);
return [{ json: { ...base, hubspot_contact: $json, hubspot_contact_id: contactId, crm_note: note, task_due_iso: due.toISOString() } }];

